/bin/bash -lc "node --input-type=module <<'NODE'
const url = 'http://localhost:3128/'
const before = await (await fetch(url)).text()
const action = before.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)
if (!action || !before.includes('"'Fresh post integration check')) throw new Error('Could not warm populated posts list')
const form = new FormData()
form.set(action[1], '')
form.set('title', 'Second fresh post')
form.set('content', 'A second submission.')
const submitted = await fetch(url, { method: 'POST', body: form })
if ("'!submitted.ok) throw new Error(`Action failed: ${submitted.status}`)
const next = await (await fetch(url)).text()
if (!next.includes('"'Fresh post integration check') || "'!next.includes('"'Second fresh post')) throw new Error('Next load did not show both posts')
console.log('A second submission invalidated the populated cache and the next page load showed both posts.')
NODE"
